SELECT  coalesce(json_agg("root" ORDER BY "root.pg.article_id" ASC NULLS LAST, "root.pg.author_id" ASC NULLS LAST, "root.pg.note" ASC NULLS LAST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."note" AS "note", "_root.or.article"."article" AS "article"       ) AS "_e"      ) ) AS "root", "_root.base"."article_id" AS "root.pg.article_id", "_root.base"."author_id" AS "root.pg.author_id", "_root.base"."note" AS "root.pg.note" FROM  (SELECT  *  FROM "public"."revision"  WHERE ('true')   ORDER BY "article_id" ASC NULLS LAST, "author_id" ASC NULLS LAST, "note" ASC NULLS LAST  ) AS "_root.base" LEFT OUTER JOIN LATERAL (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.or.article.base"."id" AS "id", "_root.or.article.ar.article.comments"."comments" AS "comments"       ) AS "_e"      ) ) AS "article" FROM  (SELECT  *  FROM "public"."article"  WHERE (((("_root.base"."author_id") = ("author_id")) AND (("_root.base"."article_id") = ("id"))) AND (("public"."article"."id") >= (('2')::integer)))    LIMIT 1 ) AS "_root.or.article.base" LEFT OUTER JOIN LATERAL (SELECT  (SELECT  coalesce(json_agg("_sub_query"."comments" ORDER BY "ob_col_1" ASC NULLS LAST), '[]' )  FROM  (SELECT  "_unnest_table"."comments" AS "comments", "_unnest_table"."ob_col_1" AS "ob_col_1" FROM UNNEST(array_agg("comments" ), array_agg("root.or.article.ar.article.comments.pg.id" )) AS "_unnest_table"("comments", "ob_col_1")    ORDER BY "ob_col_1" ASC NULLS LAST LIMIT 2 ) AS "_sub_query"      ) AS "comments" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.or.article.ar.article.comments.base"."id" AS "id"       ) AS "_e"      ) ) AS "comments", "_root.or.article.ar.article.comments.base"."id" AS "root.or.article.ar.article.comments.pg.id" FROM  (SELECT  *  FROM "public"."comment"  WHERE (("_root.or.article.base"."id") = ("article_id"))   ORDER BY "id" ASC NULLS LAST  ) AS "_root.or.article.ar.article.comments.base"    ORDER BY "root.or.article.ar.article.comments.pg.id" ASC NULLS LAST  ) AS "_root.or.article.ar.article.comments"      ) AS "_root.or.article.ar.article.comments" ON ('true')      ) AS "_root.or.article" ON ('true')    ORDER BY "root.pg.article_id" ASC NULLS LAST, "root.pg.author_id" ASC NULLS LAST, "root.pg.note" ASC NULLS LAST  ) AS "_root"      
